window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-doencas-benignas-da-mama"]={"block":"anki:ginecologia-doencas-benignas-da-mama","label":"Anki · Doenças Benignas da Mama","count":96,"questions":[{"id":"anki-ginecologia-doencas-benignas-da-mama-a3b717e12e468512","number":"0201n","sourceNumber":"0201n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher com 43 anos de idade, IV gesta III para e 1 abortamento, refere que no seu auto-exame que faz das mamas durante o banho, observou um “caroço” na mama esquerda. O médico solicitou uma ultrassonografia que mostrou uma imagem anecoide regular de limites precisos, com reforço posterior, eixo horizontal maior que o sagital. Qual a hipótese mais provável?","options":{"A":"Carcinoma filodes.","B":"Fibroadenoma.","C":"Câncer de mama.","D":"Cisto complexo papilifero.","E":"Cisto mamário."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149455","ankiGuid":"u~rYk(m``6"},{"id":"anki-ginecologia-doencas-benignas-da-mama-4dff8ce939c7d0af","number":"0202n","sourceNumber":"0202n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 27 anos, G1P1, usuária de DIU de cobre, menstruando regularmente. Queixa-se de dor intensa em quadrante supero lateral da mama direita, há 3 meses, com piora importante pré-menstrual e melhora parcial após. Está preocupada com histórico de câncer na família, pois tia avó materna teve câncer de mama aos 68 anos. Exame físico: mamas sem nódulos ou lesões. Cadeias linfonodais sem alterações. Dor à Ultrassonografia de mamas realizadas há 10 dias: cistos mamários bilaterais, maior diâmetro 0,5 cm, BI RADS:2. Qual a melhor conduta?","options":{"A":"Retorno com ultrassonografia de mamas em 6 meses.","B":"Solicitar ressonância magnética das mamas.","C":"Tranquilizar e prescrever anti-inflamatório tópico.","D":"Teste terapêutico com tamoxifeno 20 mg/dia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149603","ankiGuid":"xVtY@T`_?f"},{"id":"anki-ginecologia-doencas-benignas-da-mama-a119a55c6390d719","number":"0203n","sourceNumber":"0203n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher com 65 anos chega ao consultório de ginecologia com queixa de aumento da mama direita. Ao exame, f o i evidenciada uma úlcera na mama direita com dilatação venosa importante. O histopatológico da biópsia revelou comprometimento de tecido epitelial e conjuntivo com cistos que apresentam projeções em forma de folhas no seu interior. O quadro acima é característico do seguinte tumor mamário:","options":{"A":"Fibroadenoma simples.","B":"Papiloma intraductal.","C":"Lipomas.","D":"Hamartomas.","E":"Tumor Phyllodes."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149604","ankiGuid":"J2&u,]e,Hk"},{"id":"anki-ginecologia-doencas-benignas-da-mama-342a6e8400fa7f62","number":"0204n","sourceNumber":"0204n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 50 anos, G1P1, procura o consultório do ginecologista com história de descarga papilar, serosanguinolenta espontânea por um único orifício papilar. No exame da mama esquerda, percebe-se dor à palpação local, evidenciando-se descarga monoductal e presença de tumor. O exame ecográfico revela dilatação ductal e tumor retroareolar. Segundo esses dados, qual o provável diagnóstico?","options":{"A":"Adenomas","B":"Tumor Phyllodes","C":"Fibroadenoma","D":"Papiloma intraductal"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149605","ankiGuid":"e[53JvdjGI"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b3ec21c7cec1d04a","number":"0205n","sourceNumber":"0205n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Diversas doenças podem ser acompanhadas de processo inflamatório nas mamas, destacando-se, dentre elas, a doença de Mondor, mastite diabética, sarcoidose, mastite actínica, mastite por lúpus eritematoso disseminado e mastite granulomatosa. Dentre os tipos de mastites crônicas tem-se:","options":{"A":"a mastite actínica, que se caracteriza por flebite superficial autolimitada, benigna, caracterizada por cordão doloroso, que acompanha o trajeto venoso cutâneo da mama.","B":"a doença de Mondor, que é decorrente de radioterapia mamária, devido a esclerose progressiva da íntima vascular. Caracteriza-se por hiperemia, dor e aumento da temperatura da mama.","C":"a mastite diabética também conhecida como mastite obliterante, comedomastite ou mastite de células plasmáticas, que acomete os ductos lactíferos subareolares e caracteriza-se pela dilatação ductal com acúmulo de detritos celulares.","D":"a mastite granulomatosa, que é uma inflamação de causa desconhecida, caracterizada por reação granulomatosa crônica composta por células epitelióides, células gigantes multinucleadas dos tipos corpo estranho e de Langhans."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149606","ankiGuid":"Au*4gwW2}k"},{"id":"anki-ginecologia-doencas-benignas-da-mama-c98ec96723522b5e","number":"0206n","sourceNumber":"0206n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 11 anos de idade com mãe com câncer de mama apresenta lesão nodular retroareolar mama direita com 1,5cm. Qual a melhor conduta?","options":{"A":"Mamografia e punção biopsia.","B":"Observar e repetir exame clínico em 1 a 2 anos.","C":"Exerese do nódulo e estudo anatomo patológico.","D":"Ecografia, mamografia e ressonância magnética.","E":"Ecografia de mama e punção aspirativa com agulha fina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149607","ankiGuid":"sx5D[R;0s|"},{"id":"anki-ginecologia-doencas-benignas-da-mama-6f8d691f1d519a6c","number":"0207n","sourceNumber":"0207n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"da mama Assinale a alternativa correta quanto às lesões inicialmente benignas de mama.","options":{"A":"Adenomas são neoplasias epiteliais com elementos estromais densos. Possui moderado risco de malignização.","B":"Hiperplasia estromal pseudoangiomatosa geralmente tem aparência de uma massa mista, bem definida e com calcificações.","C":"Papiloma intraductal sem atipia consiste em uma matriz de células papilares que crescem da parede do ducto, sempre únicos, com risco de malignização superior a 50%.","D":"Fibroadenomas simples são tumores sólidos benignos que contêm tecido fibroso e glandular. Não é necessária a extirpação cirúrgic","E":"Hiperplasia ductal sem atipia é caracterizado por um número aumentado de células no espaço ductal. O risco de evolução para o câncer de mama subsequente é de moderado a alto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149608","ankiGuid":"f?#m6[W<_H"},{"id":"anki-ginecologia-doencas-benignas-da-mama-2fb0e4109ade8c64","number":"0208n","sourceNumber":"0208n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 42 anos de idade refere nódulo de mama esquerda de 2 centímetros há 3 meses. Foi à UBS e o médico tentou fazer uma punção e não veio líquido. A conduta indicada a seguir, dentre as abaixo, é","options":{"A":"indicar mamotomia para retirada do nódulo.","B":"realizar ultrassonografia de mamas.","C":"realizar mamografia bilateral.","D":"indicar quadrantectomia e radioterapia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149609","ankiGuid":"upF30,ES,k"},{"id":"anki-ginecologia-doencas-benignas-da-mama-8dc1664aa11b82f8","number":"0209n","sourceNumber":"0209n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 54 anos, menopausada, tem observado saída de secreção escura (marrom-esverdeada) por vários ductos das papilas mamárias bilateralmente, há cerca de seis meses. Nega qualquer antecedente pessoal ou familiar de doença mamária. Não é tabagista e o exame clínico das mamas é normal, exceto por descarga papilar bilateral, com secreção fluida, escura, por vários ductos. A mamografia recente mostra BIRADS 2. Qual o diagnóstico mais provável?","options":{"A":"Abscesso subareolar.","B":"Ectasia ductal.","C":"Papiloma intra-ductal.","D":"Carcinoma \"in situ\"."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149610","ankiGuid":"HnOs5PjM-7"},{"id":"anki-ginecologia-doencas-benignas-da-mama-0571ee0528ed8d7a","number":"0210n","sourceNumber":"0210n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"“(...) é caracterizada por proliferação anárquica de dúctulos compostos somente por células epiteliais, em meio a tecido adiposo e estroma mamário, sem reação estromal. Esses dúctulos têm contornos arredondados, não apresentam células mioepiteliais, embora exista camada basal, e as células que os revestem são cuboidais, pequenas, sem atipias significativas. A luz apresenta secreção eosinofílica densa. A forma atípica da lesão apresenta atipias citológicas e/ou arquiteturais. No estudo imunoistoquímico, as células epiteliais são negativas para receptores de estrogênio e progesterona, não expressam HER2 e são positivas para proteína S100. (...)\" A descrição histológica acima diz respeito à:","options":{"A":"Hiperplasia ductal atípica.","B":"Atipia epitelial plana.","C":"Adenose microglandular.","D":"Esferulose colagênica.","E":"Hiperplasia sem atipias."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149613","ankiGuid":"D%2/9^kGR!"},{"id":"anki-ginecologia-doencas-benignas-da-mama-86795e2fddceda01","number":"0211n","sourceNumber":"0211n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"A mastalgia é classificada quanto à origem em verdadeira (proveniente do tecido mamário) ou referida (extra-mamária, geralmente proveniente da parede torácica). A mastalgia verdadeira ainda pode ser subdividida em cíclica e acíclica. Sobre a mastalgia cíclica, é correto afirmar:","options":{"A":"Pode acontecer em mulheres na pós-menopausa.","B":"Exames de imagem complementares são necessários na ausência de alterações no exame físico.","C":"A utilização de implantes mamários pode aumentar a incidência de mastalgia cíclica.","D":"Tamoxifeno pode ser usado em casos refratários a analgésicos e anti-inflamatorios.","E":"A amenorreia induzida por SIU hormonal evita mastalgia cíclica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149614","ankiGuid":"C[S_(l6gmL"},{"id":"anki-ginecologia-doencas-benignas-da-mama-0a2f9f106fc740b9","number":"0212n","sourceNumber":"0212n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 45 anos de idade, eumenorreica, realizou rastreamento que identificou nódulo mamário suspeito em quadrante superolateral direito. Submeteu-se a exérese completa da lesão e o resultado foi fibroadenoma complexo. Qual é a conduta adequada?","options":{"A":"Tamoxifeno","B":"Raloxifeno","C":"Quadrantectomia","D":"Seguimento"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149615","ankiGuid":"pG)6NBm7:b"},{"id":"anki-ginecologia-doencas-benignas-da-mama-853cd84e0de93cd0","number":"0213n","sourceNumber":"0213n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Primípara, 4° dia de puerpério após cesárea por feto pélvico na 36ª de gestação, está no alojamento conjunto. O recém- nascido pesou 2400 gramas, nasceu em boas condições e está com a mãe. Hoje, a paciente reclamou de muita dor mamária. Sem outras queixas. A paciente fez mamoplastia de aumento há dois anos. Exame físico: temperatura 38,0º C (oral), dor, hiperemia leve e aumento de volume em ambas as mamas. Fissuras em complexo aréola mamilar à esquerda (Figura abaixo). Palpação: mamas endurecidas em ambos os quadrantes externos, expressão láctea positiva bilateral.\n\nO restante do exame físico está normal. Quais são as melhores condutas para o caso?","options":{"A":"Analgésico e ordenha mamária.","B":"Clindamicina oral e compressas mornas.","C":"Cabergolina e enfaixamento mamário.","D":"Oxacilina endovenosa e compressas frias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-bcb6d97553f65d03fd5363a82f6193fcaad88386.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149616","ankiGuid":"k`[cGqb~;x"},{"id":"anki-ginecologia-doencas-benignas-da-mama-aa43706e2fff00ab","number":"0214n","sourceNumber":"0214n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 35 anos queixa-se de mastalgia de intensidade moderada, quase todos os meses, antes das menstruações. AP: G0P0. AF: mãe recentemente diagnosticada com câncer de mama aos 61 anos. Exame das mamas: desconforto à palpação dos quadrantes superolaterais bilateralmente. A conduta é","options":{"A":"evitar suporte mamário (sutiã, top).","B":"prescrever anti-inflamatórios não esteroidais tópicos ou orais.","C":"iniciar rastreamento anual com mamografia e ressonância magnética das mamas.","D":"prescrever óleo de prímula e vitamina D, medidas comprovadamente eficazes."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149617","ankiGuid":"M;8FUcJPe3"},{"id":"anki-ginecologia-doencas-benignas-da-mama-fee6a894a1f69c10","number":"0215n","sourceNumber":"0215n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 42a, retorna para resultado de biópsia excisional de nódulo de mama esquerda BI- RADS® 4: fibroadenoma simples, com achados no parênquima adjacente ao nódulo de hiperplasia estromal pseudo-angiomatosa, metaplasia apócrina e hiperplasia lobular atípica. É CONSIDERADA LESÃO PRECURSORA PARA O DESENVOLVIMENTO DE CÂNCER DE MAMA COM RISCO MODERADO:","options":{"A":"Metaplasia apócrina.","B":"Hiperplasia lobular atípica.","C":"Fibroadenoma simples.","D":"Hiperplasia estromal pseudoangiomatosa."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149618","ankiGuid":"Atd}GSfa(^"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5f237e62ac9b60ab","number":"0216n","sourceNumber":"0216n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Menina, 9 anos de idade, vem à consulta de rotina. O pai está preocupado pois recentemente notou uma nodulação na mama direita da filha. Relata que avó paterna faleceu de câncer de mama aos 49 anos. Ao exame clínico nota-se uma elevação da aréola e papila a direita, formando uma pequena saliência, com palpação fibroelástica. Sem alterações do lado esquerdo. Sem outras alterações ao exame clínico. A conduta é:","options":{"A":"Solicitar ultrassonografia de mama.","B":"Solicitar prolactina, TSH e cortisol.","C":"Manter conduta expectante.","D":"Realizar punção aspirativa por agulha fina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149619","ankiGuid":"HZn+z`aj6w"},{"id":"anki-ginecologia-doencas-benignas-da-mama-01e5840e84858318","number":"0217n","sourceNumber":"0217n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Você é médico da atenção básica à saúde e participará de evento de capacitação do corpo de enfermagem, em sua Unidade de Saúde, sobre prevenção e diagnóstico de mastites. Em reuniões semanais, você compartilha com a equipe informações importantes sobre o tema. A respeito de mastites durante o período do aleitamento, assinale a alternativa correta.","options":{"A":"A mastite pode ocorrer durante todo o período do aleitamento; é mais frequente, porém, na primeira semana pós-parto.","B":"O diagnóstico de mastite é clínico, podendo ser complementado com exames bacteriológicos e de imagem.","C":"Durante o pré-natal, os cuidados dispensados com os mamilos devem incluir exposição ao sol e uso de sabonetes e lubrificantes, a fim de evitar infecções mamárias puerperais.","D":"Quando a ordenha do leite for necessária, deve-se preferir o uso de bombas extratoras, para reduzir o risco de trauma.","E":"O principal diagnóstico diferencial da mastite é o ingurgitamento mamário, que é unilateral e acompanhado por febre alta."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149620","ankiGuid":"OM!gcU2mKE"},{"id":"anki-ginecologia-doencas-benignas-da-mama-386373ef7d488a13","number":"0218n","sourceNumber":"0218n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Sobre a mastalgia, sabe-se que:","options":{"A":"na mastalgia acíclica, a dor é difusa e bilateral, variando ao longo do ciclo menstrual, intensificando na última semana do ciclo e melhorando após a menstruação.","B":"na mastalgia cíclica, a dor é frequentemente localizada e unilateral, em geral causada por cistos, mastites, traumas e tromboflebite superficial.","C":"o tratamento inicial na mastalgia acíclica é preferencialmente feito com tamoxifeno por um período de três a cinco dias.","D":"no tratamento da mastalgia, são importantes as medidas comportamentais como atividade física, dieta pobre em lipídios, diminuição do peso, controle da ansiedade, abolição do tabagismo e outros hábitos são importantes no tratamento da mastalgia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149621","ankiGuid":"o8IXhS>@Tp"},{"id":"anki-ginecologia-doencas-benignas-da-mama-c8f72bce15edb838","number":"0219n","sourceNumber":"0219n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 38 anos de idade com filho de 20 anos, apresenta queixas de derrame papilar em mama esquerda e cuja citologia oncótica mostrou-se negativa para malignidade e exames de imagem normal , apenas com presença de hemácias. Qual será a melhor conduta?","options":{"A":"Realizar PET SCAN.","B":"Indicar ressecção cirúrgica de ductos.","C":"Repetir imediatamente nova citologia.","D":"Aguardar seis meses e repetir a citologia.","E":"Indicar core Biopsy dos ductos principais da mama."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149622","ankiGuid":"qvf9BPs{#|"},{"id":"anki-ginecologia-doencas-benignas-da-mama-6f09cffa45783c1b","number":"0220n","sourceNumber":"0220n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 52a, G3C3A0, comparece no Centro de Saúde por nódulo indolor em mama esquerda, há três meses. Refere irregularidade menstrual, e fogachos. Mamografia: BIRADS® 0. Ultrassonografia mamária: lesão cística em mama esquerda, com conteúdo predominantemente anecoico, sem debris ou áreas sólidas, com reforço acústico posterior, BIRADS® 2. Exame físico: mama esquerda com discreto abaulamento da pele na junção dos quadrantes superiores à inspeção estática; à palpação, identificada nodulação única, bem delimitada e móvel, aproximadamente 25 mm de diâmetro. Mama direita normal. Expressão das árvores ductais negativas bilateralmente. Axilas e fossas supraclaviculares bilateralmente livres. A CONDUTA É:","options":{"A":"Excisão cirúrgica.","B":"Acompanhamento ginecológico de rotina anual.","C":"Estadiamento para câncer de mama.","D":"Punção aspirativa com agulha fina."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149623","ankiGuid":"oae2uHVfx1"},{"id":"anki-ginecologia-doencas-benignas-da-mama-8ff48efa7a9f553f","number":"0221n","sourceNumber":"0221n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Uma paciente de quarenta anos de idade, sem antecedente pessoal ou familiar de neoplasias, refere ter realizado autoexame da mama pela primeira vez há quatro meses, tendo notado pequeno nódulo em mama esquerda, menor que 1 cm. Como não apresentava dor ou qualquer outro sintoma, convenceu-se de que não deveria se preocupar. Há um dia, ao observar-se no espelho, notou abaulamento em mama esquerda. À palpação, sentiu nódulo de cerca de 5 cm no mesmo local em que acreditava ter sentido algo há quatro meses. Nega dor, descarga papilar ou qualquer outra sintomatologia. Ao exame, identificou-se nódulo ocupando todo o quadrante inferomedial da mama esquerda, medindo cerca de 5 cm, duro, móvel e com contornos regulares. Ausência de linfonodomegalia em cadeias axilares e supraclaviculares. A mamografia evidenciou nódulo oval medindo 4,6 cm, circunscrito e hiperdenso. Com base nessa situação hipotética, o diagnóstico mais provável e a conduta a ser adotada são, respectivamente,","options":{"A":"fibroadenoma e conduta expectante.","B":"fibroadenoma e quadrantectomia.","C":"tumor filoides e conduta expectante.","D":"tumor filoides e quadrantectomia.","E":"carcinoma inflamatório e quimioterapia neoadjuvante."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149624","ankiGuid":"F>Z|?k{h&x"},{"id":"anki-ginecologia-doencas-benignas-da-mama-d3bc9004c37a9dd1","number":"0222n","sourceNumber":"0222n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 45 anos de idade queixa-se de saída de secreção amarelada pelos mamilos. Refere menopausa aos 43 anos e, desde então faz uso de terapia estroprogestativa por adesivos transdérmicos. Ao exame, observa-se saída de secreção espessa e esverdeada, por vários ductos em ambos os mamilos, durante expressão. O diagnóstico mais provável é de:","options":{"A":"adenoma de hipófise.","B":"carcinoma ductal invasivo.","C":"ectasia ductal.","D":"alterações fibrocísticas de mamas.","E":"carcinoma in situ."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149625","ankiGuid":"Kk];[.j0|,"},{"id":"anki-ginecologia-doencas-benignas-da-mama-0f7335407295d1d4","number":"0223n","sourceNumber":"0223n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 37 anos de idade com queixa de saída de secreção avermelhada pelo mamilo esquerdo há 2 meses. Refere que o fluxo é espontâneo. Ao exame, as mamas são simétricas, sem abaulamento ou retração e sem nódulos palpáveis. À expressão mamilar notamos um fluxo papilar (ver imagem). Foi realizado ultrassonografia e mamografia com BIRADS® 1.\n\nQual a conduta mais adequada para a elucidação diagnóstica?","options":{"A":"Coleta de citologia do fluido papilar.","B":"Biópsia cirúrgica da unidade mamária.","C":"Realizar ductografia mamária.","D":"Realizar ressonância magnética."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-562ddf9218b3b3ed8fd3b7c75df4857bf52cee7f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149626","ankiGuid":"kF)rC7TC@H"},{"id":"anki-ginecologia-doencas-benignas-da-mama-bdc0e76f00388ec8","number":"0224n","sourceNumber":"0224n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"A propedêutica clínica é fundamental para o acerto no provável diagnóstico de doenças mamárias. Assinale a alternativa correta em relação a esta propedêutica:","options":{"A":"A mastite com presença de abscesso deve ser tratada com drenagem cirúrgica ou punção com agulha grossa.","B":"Mulher com 60 anos e queixa de aparecimento de tumor em mama, até se provar o contrário, é portadora de fibroadenoma.","C":"Exame físico deve ser realizado preferencialmente na fase lútea do ciclo menstrual.","D":"Fluxo mamário que tem importância clínica é espontâneo, uniductal, bilateral e amarelado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149627","ankiGuid":"G8{T/Y,2.!"},{"id":"anki-ginecologia-doencas-benignas-da-mama-3c2c01fb78edc86e","number":"0225n","sourceNumber":"0225n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Em relação às alterações benignas da mama, qual das alternativas abaixo é INCORRETA?","options":{"A":"Cistos complicados apresentam ecos internos à ultrassonografia e, em geral devem ser investigados com punção aspirativa.","B":"Fibroadenomas são lesões benignas que geralmente se apresentam desde a adolescência.","C":"Descargas mamilares multiductais de cor esverdeada ou marrom que ocorrem apósexpressão manual devem ser consideradas patológicas e merecem avaliação complementar.","D":"A galactorreia pode ser induzida pelo uso de medicamentos como: clorpromazina,atenolol e ranitidina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149628","ankiGuid":"n;O5|o](1w"},{"id":"anki-ginecologia-doencas-benignas-da-mama-288a554a6376058d","number":"0226n","sourceNumber":"0226n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 38 anos de idade com filho de 20 anos apresenta queixas de derrame papilar em mama esquerda, cuja citologia oncótica mostrou-se negativa para malignidade, apenas com presença de hemácias, e exames de imagem normais. Qual será a melhor conduta?","options":{"A":"Realizar PET SCAN.","B":"Indicar ressecção cirúrgica de ductos.","C":"Repetir imediatamente nova citologia.","D":"Aguardar 6 meses e repetir a citologia.","E":"Indicar core Biopsy dos ductos principais da mama."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149629","ankiGuid":"v4NxBgA{^1"},{"id":"anki-ginecologia-doencas-benignas-da-mama-aa2ad93227bc62f9","number":"0227n","sourceNumber":"0227n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher com 45 anos vai ao consultório de ginecologia com mama direita apresentando proliferação exofítica próxima à papila. Revela que o crescimento foi lento. O aspecto é friável de coloração vinhosa. A descarga papilar é serosanguinolenta, espontânea, unilateral e por um único orifício. Refere dor à palpação. O exame ecográfico demonstra segmento ductal dilatado, padrões hipoecoicos acoplados à parede com crescimento verrocoso. Esse quadro revela o seguinte tipo de tumor mamário:","options":{"A":"Fibroadenoma simples.","B":"Papiloma intraductal.","C":"Tumor Phyllodes.","D":"Hamartomas.","E":"Lipomas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149630","ankiGuid":"id;x,|H/Dy"},{"id":"anki-ginecologia-doencas-benignas-da-mama-8ae0cdc62dc94270","number":"0228n","sourceNumber":"0228n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 50 anos, assintomática, com exame físico normal, faz sua primeira mamografia bilateral que mostra um nódulo de 10 mm em quadrante lateral superior da mama esquerda. Realizou então uma ultrassonografia mamária que mostrou tratar-se de um cisto de paredes finas e conteúdo anecóico com reforço acústico posterior. Qual a melhor conduta a ser adotada?","options":{"A":"Mamografia e ultrassonografia de controle anual.","B":"Exérese do nódulo.","C":"Core biópsia guiada por ultrassonografia.","D":"Ressonância nuclear magnética."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149631","ankiGuid":"Q02{J,Fy8,"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5acae48d3a370d5e","number":"0229n","sourceNumber":"0229n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Puérpera de 22 anos, décimo dia de pós-parto cesariana eletiva por apresentação pélvica, procura a UBS com queixa de há dois dias estar apresentando dor intensa na mama direita, dificuldade para amamentar e febre. Ao exame físico: aparência cansada, PA 110/60mmHg, FC 110bpm, temperatura axilar 38,5°C. Mama esquerda sem alterações, mama direita dolorosa, com hiperemia e área de edema no quadrante superior externo, sem sinais de flutuação. Ausculta respiratória sem alterações. Ausculta cardíaca: bulhas normofonéticas, ritmo cardíaco regular em dois tempos. Assinale a conduta MAIS ADEQUADA.","options":{"A":"Encaminhar para a maternidade de referência para abordagem cirúrgica","B":"Prescrever ibuprofeno e cefalexina por via oral, e calor local","C":"Solicitar ultrassonografia das mamas e prescrever antitérmico","D":"Suspender a amamentação e solicitar ultrassonografia das mamas"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149632","ankiGuid":"QAm{m5h6U]"},{"id":"anki-ginecologia-doencas-benignas-da-mama-bee4e0b39503b8d0","number":"0230n","sourceNumber":"0230n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"São várias as desordens benignas das mamas. Os nódulos mamários compreendem os fibroadenomas, cistos, lipomas, hamartomas, adenomas, papilomas e tumor filoides. Diversas doenças não infecciosas podem ser acompanhadas de processo inflamatório nas mamas, causando mastalgia, destacando-se a doença de Mondor, mastite diabética, sarcoidose, mastite actínica, mastite por lúpus eritematoso disseminado e mastite oleogranulomatosa. Tendo em vista essas desordens benignas,","options":{"A":"a síndrome de Tietze e a doença de Mondor são causas de mastalgia cíclica e são tratadas com estrogênio em doses baixas.","B":"o fibroadenoma é um tumor benigno da mama com pico de incidência entre 55 e 60 anos.","C":"o tumor filodes se assemelha ao fibroadenoma, mas é caracterizado por uma menor celularidade do estroma.","D":"a mastite granulomatosa é uma afecção inflamatória benigna com etiologia incerta, e o tratamento de eleição se faz com prednisona."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149633","ankiGuid":"rpN}KC8{r["},{"id":"anki-ginecologia-doencas-benignas-da-mama-7028efaa014c1b37","number":"0231n","sourceNumber":"0231n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 60 anos de idade, apresenta nódulo irregular de 8 mm na mama direita identificado na mamografia e na ultrassonografia. O resultado da biópsia revelou hiperplasia ductal atípica. Qual é a próxima conduta?","options":{"A":"Ressonância magnética","B":"Controle com mamografia e ultrassonografia em 6 meses","C":"Terapia com tamoxifeno","D":"Exérese da lesão identificada por fio metálico ou radioisótopo","E":"Terapia com anastrozol"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149634","ankiGuid":"Fls`ge/5lQ"},{"id":"anki-ginecologia-doencas-benignas-da-mama-66b7b05e0eb566cc","number":"0232n","sourceNumber":"0232n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente procura mastologista com queixa de descarga papilar. No exame das mamas fica evidente que se trata de fluxo benigno porque o mesmo é:","options":{"A":"uniductal bilateral.","B":"uniductal, unilateral.","C":"multiductal, unilateral.","D":"multiductal, bilateral."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149635","ankiGuid":"LjoZ*I80|_"},{"id":"anki-ginecologia-doencas-benignas-da-mama-4ce30a62cc3a88ee","number":"0233n","sourceNumber":"0233n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Uma puérpera de primeira gestação, ansiosa, no décimo dia de puerpério, comparece ao atendimento referindo dor mamária e febre não aferida. Ao exame físico, a mama direita apresenta-se dolorosa, endurecida, sem sinais flogísticos. A temperatura axilar é de 37,3 graus C. A conduta que não se aplica nesse momento é:","options":{"A":"compressa gelada local.","B":"antibiótico.","C":"antiinflamatório via oral.","D":"esvaziamento mamário."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149636","ankiGuid":"KZBHpN>,CB"},{"id":"anki-ginecologia-doencas-benignas-da-mama-67a5f55d08273a91","number":"0234n","sourceNumber":"0234n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 40 anos de idade, nuligesta, queixa-se de saída de secreção esbranquiçada pelos mamilos há 1 mês. Ao exame, não há nódulos palpáveis na mama e a expressão mostra saída de líquido branco de vários ductos, bilateralmente. A mamografia mostra calcificação grosseira no quadrante lateral da mama esquerda. Nesse caso:","options":{"A":"É fundamental a ultrassonografia complementar da mama à procura de lesões suspeitas.","B":"É indispensável a realização da citologia oncológica do líquido secretado.","C":"É necessário realizar biópsia cirúrgica da área de calcificação da mama.","D":"Trata-se de possível papiloma intraductal, devendo-se repetir a mamografia em 6 meses.","E":"Trata-se de galatorreia, devendo-se pesquisar o uso de psicotrópicos e dosar prolactina."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149637","ankiGuid":"KM==R*m=%V"},{"id":"anki-ginecologia-doencas-benignas-da-mama-ad7056fe756259fe","number":"0235n","sourceNumber":"0235n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Um dos tumores mamários mais prevalente é o fibroadenoma, que geralmente atinge mulheres na faixa etária de 18 a 30 anos. Em relação a este tumor, é correto afirmar que","options":{"A":"seu tratamento é sempre cirúrgico pelo risco de carcinoma em fibroadenoma.","B":"é contraindicado o uso de anticoncepcionais hormonais combinados nestas pacientes.","C":"o dispositivo intrauterino com levonorgestrel aumenta em 30% o volume dos fibroadenomas.","D":"se trata de tumor do tecido conjuntivo mamário e, por isso, é bastante móvel.","E":"se trata de tumor benigno misto."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149638","ankiGuid":"t&eQ=rB|;N"},{"id":"anki-ginecologia-doencas-benignas-da-mama-fd868c11ca3a01e5","number":"0236n","sourceNumber":"0236n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 45 anos apresenta lesão cística da mama. Nesse caso, a biópsia não é necessária quando se observa","options":{"A":"cisto complexo.","B":"líquido acastanhado na aspiração.","C":"presença de massa intracística.","D":"persistência do tumor após aspiração.","E":"lesão eritematosa em casca de laranja."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149639","ankiGuid":"Ls+Tlv)C:&"},{"id":"anki-ginecologia-doencas-benignas-da-mama-6bbfa5ab306a8db5","number":"0237n","sourceNumber":"0237n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 50 anos de idade queixa-se de saída de secreção esverdeada, pelo mamilo esquerdo, ao realizar autoexame de mama, que apareceu há cerca de 1 mês. É tabagista e teve 2 partos normais, sendo o último há 20 anos. O diagnóstico mais provável é:","options":{"A":"Ectasia ductal.","B":"Doença de Paget.","C":"Carcinoma intraductal.","D":"Abscesso mamário.","E":"Papiloma intraductal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149640","ankiGuid":"OWI@O:9$$|"},{"id":"anki-ginecologia-doencas-benignas-da-mama-ee0a1987a773f674","number":"0238n","sourceNumber":"0238n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 45 anos de idade, queixa-se de saída de sangue pelo mamilo. Ao exame observa-se saída de derrame papilar sanguinolento por ducto único à direita. Palpação normal do parênquima mamário e axilar. Qual é o exame mais adequado para a investigação diagnóstica?","options":{"A":"Citologia do derrame.","B":"Mamografia.","C":"PET-CT.","D":"Ressonância magnética."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149641","ankiGuid":"Esn]=[DwsV"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5b46c839e98c16e5","number":"0239n","sourceNumber":"0239n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Assinale a afirmativa correta quanto às doenças benignas das mamas:","options":{"A":"O fibroadenoma com 1cm não palpável em paciente jovem tem indicação cirúrgica.","B":"O agente mais encontrado em mastites é a Klebsiella.","C":"O cisto complexo com conteúdo sólido é classificado como BIRADS 5.","D":"O fluxo papilar hemorrágico, espontâneo, uniductal e intermitente tem indicação cirúrgica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149642","ankiGuid":"DFhxtX}nL="},{"id":"anki-ginecologia-doencas-benignas-da-mama-53064aa60f92a5de","number":"0240n","sourceNumber":"0240n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 25 anos, assintomática, procura atendimento para exame ginecológico preventivo. Gesta=0, Menarca aos 13 anos. Faz uso de anovulatório oral. Nega antecedentes pessoais e familiais de neoplasias. Não foi observada anormalidade no exame clinico ginecológico e mamário. Foi colhido colpocitologia oncótica. Qual exame está indicado para avaliação de suas mamas","options":{"A":"Mamografia","B":"Ultrassom","C":"Mamografia e Ultrassom de mama","D":"Nenhum exame de imagem"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149643","ankiGuid":"n.H@b2Wsyp"},{"id":"anki-ginecologia-doencas-benignas-da-mama-4f846903ac2e5ec7","number":"0241n","sourceNumber":"0241n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 28a, comparece em consulta ginecológica com queixa de dor nas mamas há 15 dias. Refere que a dor tem ritmo catamenial, com piora na segunda fase do ciclo menstrual, e melhora importante na primeira fase. Antecedentes pessoais: Nega trauma, mastite e tabagismo, nunca fez mamografia e refere uso regular de pílula anticoncepcional oral combinada, hoje no quarto dia de pausa. Antecedentes familiares: negativos para doenças oncológicas. Trabalha como manicure. Exame físico: mamas: médio volume, sem alterações às inspeções estática e dinâmica, palpação dolorosa em quadrantes superiores laterais bilateralmente, ausência de descarga papilar bilateralmente, regiões axilares sem linfonodomegalia, dor ao pinçamento da borda lateral da musculatura peitoral. A CONDUTA É:","options":{"A":"Não solicitar exames complementares.","B":"Solicitar mamografia.","C":"Mudar o método anticoncepcional.","D":"Solicitar ressonância magnética das mamas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149644","ankiGuid":"w$>+K:&Z@?"},{"id":"anki-ginecologia-doencas-benignas-da-mama-33fb8165c9062054","number":"0242n","sourceNumber":"0242n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"A mastite é uma complicação durante a alimentação com leite materno exclusivo. Qual a conduta mais adequada de tratamento, a ser realizada em casos de mastite infecciosa:","options":{"A":"Iniciar antibioticoterapia sempre desde o início dos sintomas.","B":"Em casos de dor intensa, suspender amamentação na mama comprometida, ordenhar o leite e oferecer ao lactente sadio.","C":"O Streptococos pyogenes é o agente etiológico mais comum nesses casos. Iniciar penicilina.","D":"A oxacilina é a droga de escolha para o tratamento de casos leves.","E":"O uso de Lactobacillus fermentum não é alternativa eficiente ao uso de antibióticos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149645","ankiGuid":"LMxadJ[h<"},{"id":"anki-ginecologia-doencas-benignas-da-mama-7d1e6287d3618098","number":"0243n","sourceNumber":"0243n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente procurou o ambulatório de mastologia com derrame papilar unilateral, espontâneo, sanguinolento em ducto único. Qual a causa mais comum para um derrame papilar com estas carcterísticas?","options":{"A":"Medicação hormonal","B":"Prolactinoma","C":"Cancer de mama intra-ductal","D":"papiloma intra-ductal","E":"Tumor filóides"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149646","ankiGuid":"B|<4x)~A<@"},{"id":"anki-ginecologia-doencas-benignas-da-mama-60a3ed5781a9d665","number":"0244n","sourceNumber":"0244n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Na maioria das vezes, a descarga patológica do mamilo é causada por papilomas intraductais benignos. Ao avaliar uma paciente, o médico deve considerar a descarga papilar patológica se esta for:","options":{"A":"Multiductal, após expressão, láctea ou esverdeada.","B":"Uniductal, após expressão, láctea ou esverdeada.","C":"Multiductal, espontânea, serosa ou hemorrágica.","D":"Uniductal, espontânea, serosa ou hemorrágica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149647","ankiGuid":"_|h.ZBf2;"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b377bdcda70ca440","number":"0245n","sourceNumber":"0245n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente com 38 anos de idade com filho de 20 anos, apresenta queixas de derrame papilar em mama esquerda cuja citologia oncótica mostrou-se negativa para malignidade. Os exames de imagem mostraram-se normais, apenas com presença de hemácias, qual será a melhor conduta?","options":{"A":"Realizar PET SCAN.","B":"Repetir imediatamente nova citologia.","C":"Indicar ressecção cirúrgica de ductos.","D":"Aguardar 6 meses e repetir a citologia.","E":"Indicar core biopsy dos ductos principais da mama."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149648","ankiGuid":"u^Hs+-{Rs@"},{"id":"anki-ginecologia-doencas-benignas-da-mama-65820743a4800c8e","number":"0246n","sourceNumber":"0246n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 60 anos chega ao ambulatório de ginecologia com queixa de descarga papilar espontânea. Durante a avaliação, percebe-se que a descarga é uniductal e unilateral, aquosa/serosa. De acordo com o quadro acima, assinale a alternativa que contém o diagnóstico mais provável.","options":{"A":"Hiperprolactinemia","B":"Câncer mamário","C":"Mastite não puerperal","D":"Fibroadenoma","E":"Hamartoma"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149649","ankiGuid":"o-{YCbP0.u"},{"id":"anki-ginecologia-doencas-benignas-da-mama-c03e9e375c80a271","number":"0247n","sourceNumber":"0247n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"As doenças benignas da mama incluem todas as condições não malignas e classicamente não aumentam o risco para malignidade. Na maioria dos casos, o acompanhamento com exames de imagem é o procedimento mais indicado. Porém, em algumas dessas patologias, deve ser optado para exérese da lesão como, por exemplo, as que possuem um crescimento progressivo não maligno. Diante do exposto, qual das doenças benignas, com base no achado histológico por biópsia, não tem indicação de exérese?","options":{"A":"Lesão esclerosante complexa.","B":"Papiloma intraductal.","C":"Cicatriz radiada.","D":"Tumor filoide.","E":"Hamartoma."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149650","ankiGuid":"soMTuCzW-7"},{"id":"anki-ginecologia-doencas-benignas-da-mama-679dcf4386a4548f","number":"0248n","sourceNumber":"0248n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 20 anos, nuligesta, sem doenças conhecidas, refere dor mamária bilateral em ardor e peso, importante, que atrapalha suas atividades cotidianas. Localiza-se principalmente nos quadrantes externos das mamas e que antecede o fluxo menstrual. Nega qualquer outra queixa e nega antecedentes familiares de câncer. O exame clínico das mamas apresenta espassamento glandular difuso bilateral. Qual a melhor opção terapêutica para esta paciente?","options":{"A":"Vitamina E","B":"Bromocriptina","C":"Progestagênio","D":"Tamoxifeno"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149651","ankiGuid":"MWrh^o([m0"},{"id":"anki-ginecologia-doencas-benignas-da-mama-fabf1cff755559e7","number":"0249n","sourceNumber":"0249n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"O fibroadenoma de mama é mais prevalente em mulheres entre 18 e 30 anos e pode ser único ou múltiplo. Em relação a esse tumor mamário, é CORRETO afirmar:","options":{"A":"Trata-se de tumor epitelial e quase sempre é benigno.","B":"Durante a gravidez costuma diminuir de volume em razão da progesterona.","C":"Pode ser tratado cirurgicamente, em geral quando palpável e maior que 2 a 3 cm.","D":"Quando diagnosticado à ultrassonografia, deve-se fazer a core-biopsy, mesmo em situação de BI-RADS II.","E":"Quando diagnosticado, o uso de anticoncepcional hormonal oral combinado está contraindicado."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149652","ankiGuid":"u--nQz!]r6"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5f996cc114ec0688","number":"0250n","sourceNumber":"0250n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Uma paciente de 36 anos de idade realizou ultrassonografia de mamas, identificando ectasia ductal focal em mama esquerda como achado único. O exame foi realizado devido à queixa de mastalgia antecedendo a menstruação. A paciente nega descarga mamilar. Com base nesse caso hipotético, assinale a alternativa que apresenta a conduta CORRETA:","options":{"A":"Biópsia por agulha grossa.","B":"Biópsia por agulha fina.","C":"Acalmar a paciente e fazer acompanhamento anual.","D":"Controle em três meses.","E":"Controle em seis meses."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149653","ankiGuid":"bH}8@HnGGx"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b095c89d675bf9eb","number":"0251n","sourceNumber":"0251n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Em relação às lesões mamárias, é correto afirmar que","options":{"A":"cistos mamários são lesões frequentes, com características arredondadas, circunscritas e móveis, sendo que o exame ideal para identificá-los é a ultrassonografia.","B":"os fibroadenomas mamários são tumores sólidos, na maioria das vezes bilaterais e múltiplos, móveis, bem delimitados e, quando pequenos, em qualquer idade, devem permanecer em observação.","C":"a existência de dor mamária é sintoma importante na prevenção dos casos de câncer mamário, merecendo investigação.","D":"os casos de alterações funcionais benignas das mamas (AFBMs) são quadros psicossomáticos, sendo que uma terapia psicológica resolve a maioria dos casos.","E":"a identificação de ectasia ductal é indicativa de exérese dos ductos acometidos, o que melhora sobremaneira os sintomas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149654","ankiGuid":"Gy[Emrs},P"},{"id":"anki-ginecologia-doencas-benignas-da-mama-1face300bbd80c55","number":"0252n","sourceNumber":"0252n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 28 anos percebe nódulo no seio e mastalgia. Ao exame físico, seu ginecologista identifica o nódulo, afirma que provavelmente se trata de uma alteração funcional benigna da mama e solicita ultrassonografia mamária para confirmação do diagnóstico. A característica ultrassonográfica que é compatível com o diagnóstico clínico consiste em:","options":{"A":"diâmetro anteroposterior maior que o laterolateral","B":"sombra acústica posterior","C":"reforço acústico lateral","D":"conteúdo anecoico"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149655","ankiGuid":"F8+0A6y8I9"},{"id":"anki-ginecologia-doencas-benignas-da-mama-62ece61947d66635","number":"0253n","sourceNumber":"0253n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 35 anos de idade refere aparecimento de nódulo mamário, doloroso, esquerdo, há 1 mês. Neste período, observou pequeno crescimento do nódulo e dor, com necessidade do uso eventual de anti-inflamatório não hormonal. Não tem antecedentes mórbidos, pessoais ou familiares relevantes. No exame clínico, o nódulo está localizado no quadrante superolateral esquerdo, tem 3 cm de diâmetro, é móvel e tem limites regulares. O ultrassom da lesão está mostrado a seguir.\n\nConsiderando a principal hipótese para o quadro clínico e imagem apresentada, qual é a melhor conduta para o caso?","options":{"A":"Biópsia com agulha grossa.","B":"Exérese cirúrgica.","C":"Mamotomia por ultrassom.","D":"Aspirado com agulha fina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-c7e56422e814a5e1a1809a50355da6ee73c76211.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149656","ankiGuid":"pEybmAS$*]"},{"id":"anki-ginecologia-doencas-benignas-da-mama-d23991cc390da05d","number":"0254n","sourceNumber":"0254n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Qual a melhor conduta em paciente jovem (22 anos), que apresenta tumor de mama com crescimento rápido, 4 cm, indolor e consistência fibroelástica?","options":{"A":"biópsia por fragmento com agulha grossa (core-biopsy).","B":"biópsia à vácuo por mamotomia.","C":"punção aspirativa com agulha fina.","D":"tumorectomia sem margens."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149657","ankiGuid":"foX)D{ed2I"},{"id":"anki-ginecologia-doencas-benignas-da-mama-d5fb6261a4f676fe","number":"0255n","sourceNumber":"0255n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Quanto as doenças benignas das mamas pode-se afirmar que:","options":{"A":"A conduta no tumor filóides variedade borderline e, com 1 cm é mastectomia simples.","B":"O fibroadenoma é a doença mamária mais frequente na menopausa.","C":"O fluxo papilar hemorrágico, espontâneo e unilateral não é indicação de cirurgia.","D":"O cisto complexo apresenta componente sólido e é classificado como BIRADS 4"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149658","ankiGuid":"JVBK^5Sk)1"},{"id":"anki-ginecologia-doencas-benignas-da-mama-862204ef7fb77237","number":"0256n","sourceNumber":"0256n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Puérpera na 3ª semana pós-parto retorna à maternidade referindo prurido, ardor e dor mamilar. Ao exame, observou-se hiperemia e descamação da pele da região areolomamilar. O obstetra solicitou que trouxessem o recém-nascido para exame clínico da cavidade oral. A hipótese diagnóstica realizada pelo obstetra foi infecção por:","options":{"A":"Staphylococcus aureus","B":"Staphylococcus albus","C":"Candida albicans","D":"Streptococcus"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149659","ankiGuid":"h%E2m&[>e/"},{"id":"anki-ginecologia-doencas-benignas-da-mama-7925954569f4e574","number":"0257n","sourceNumber":"0257n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Entre as características dos derrames papilares, qual não é considerada suspeita de câncer?","options":{"A":"bilateral.","B":"espontâneo.","C":"aquoso.","D":"sanguinolento.","E":"uniductal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149660","ankiGuid":"E@]o$}$q=,"},{"id":"anki-ginecologia-doencas-benignas-da-mama-82447206f333e456","number":"0258n","sourceNumber":"0258n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente, 45 anos, refere descarga papilar sanguinolenta, espontânea, pela mama direita. Ao exame, não apresenta linfonodomegalias ou nódulos mamários. Sinal do ponto de gatilho positivo, com saída de secreção serossanguinolenta uniductal na mama esquerda. Nesse caso, a melhor conduta para esclarecimento diagnóstico é:","options":{"A":"Citologia da descarga papilar.","B":"Ductografia contrastada do ducto acometido.","C":"Punção aspirativa por agulha fina.","D":"Core biopsy.","E":"Excisão cirúrgica do sistema ductal terminal."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149661","ankiGuid":"ydw1EsP;t3"},{"id":"anki-ginecologia-doencas-benignas-da-mama-567ad1ed0db8c00e","number":"0259n","sourceNumber":"0259n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"As doenças das mamas são causas comuns de consulta médica devido ao grande medo do câncer. Analise as patologias de mama abaixo: I- fibroadenoma; II- adenose; III- papiloma intraductal; IV- eclasia ductal. Qual(is) da(s) seguinte(s) é(são) considerada(s) patologia(s) benigna(s)?","options":{"A":"I apenas.","B":"I e IV apenas.","C":"I, II, e IV apenas.","D":"I, II, III e IV."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149662","ankiGuid":"rn#[N%kL{y"},{"id":"anki-ginecologia-doencas-benignas-da-mama-23ff258c9ba11453","number":"0260n","sourceNumber":"0260n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"O médico de família atende uma paciente de 23 anos que comparece a Unidade de Saúde no quinto dia após parto vaginal para revisão puerperal. O recém-nascido encontra-se em aleitamento materno exclusivo. A paciente queixa-se de dificuldade para a amamentação, pois o bebê dorme a maior parte do tempo. Refere mamas dolorosas. Ao exame, o médico observou mamas edemaciadas, com pele brilhante e avermelhada bilateralmente. Não apresentou febre e mal-estar. Qual a conduta correta nesse caso?","options":{"A":"Prescrever antibiótico sistêmico.","B":"Fazer compressas mornas e evitar sutiã.","C":"Amamentar frequentemente e analgesia.","D":"Suspender a amamentação por 24 horas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149663","ankiGuid":"KL0F$*HI^c"},{"id":"anki-ginecologia-doencas-benignas-da-mama-551e9b14ee0e0ab1","number":"0264n","sourceNumber":"0264n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Quais das seguintes medicações são eficazes para o tratamento da dor mamária?","options":{"A":"Anti-inflamatório não hormonal; diurético; tamoxifeno.","B":"Lisurida; piridoxina; isoflavona","C":"Danazol; gestrinona; análogo de GnRH.","D":"Ácido gamalinoleico; cabergolina; antibiótico.","E":"Progestagênio; vitamina E; bromocriptina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149667","ankiGuid":"QX`wgTZsJ,"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5ddd1388c34dfb95","number":"0265n","sourceNumber":"0265n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 44 anos, eumenorreica, assintomática, realizou mamografia e ultrassom de mamas que identificaram cistos simples bilaterais menores que 5 mm e calcificações redondas isoladas bilaterais. Exame físico normal. Realizou mamoplastia redutora (cirurgia estética) cujo resultado patológico identificou, em mama direita, neoplasia lobular in situ grau 3, com a margem cirúrgica lateral coincidente. Dentre as alternativas abaixo, a melhor conduta é:","options":{"A":"Quadrantectomia a direita e radioterapia adjuvante.","B":"Mastectomia direita com biópsia do linfonodo sentinela.","C":"Biópsia do linfonodo sentinela e radioterapia adjuvante.","D":"Tamoxifeno 20 mg/dia por 5 anos.","E":"Controle clínico e ultrassonográfico anual."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149668","ankiGuid":"l~.lz_x@2p"},{"id":"anki-ginecologia-doencas-benignas-da-mama-14f296987c0238ae","number":"0266n","sourceNumber":"0266n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 42 anos, em uso de contraceptivo combinado oral, apresenta fluxo papilar espontâneo, aquoso, uniductal e apenas em mama esquerda. Exame clínico, ultrassonográfico e mamográfico normal. Qual a conduta correta?","options":{"A":"Exérese do ducto comprometido.","B":"Se citologia normal, controle mamográfico semestral.","C":"Orientação e acompanhamento de rotina.","D":"Punção aspirativa com agulha fina.","E":"Pesquisa de adenoma hipofisário."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149669","ankiGuid":"cAG#Bwd^4E"},{"id":"anki-ginecologia-doencas-benignas-da-mama-60765488700ff744","number":"0267n","sourceNumber":"0267n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 45 anos, queixa-se de vermelhidão e dor em região central da mama direita, além de dois episódios de febre não aferida há dois dias. AP: fumante há 30 anos, usa fluoxetina há dois anos para depressão. AF: mãe com câncer de mama aos 50 anos. EF: mama direita hiperemiada em quadrante central com aumento de temperatura local, dolorosa à palpação, área central mais amolecida, sem nódulos. A conduta imediata é:","options":{"A":"Mamografia.","B":"Encaminhar para serviço especializado.","C":"Antibioticoterapia.","D":"Biópsia incisional."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149670","ankiGuid":"LdtNA]#%j1"},{"id":"anki-ginecologia-doencas-benignas-da-mama-59964c032d4f619a","number":"0268n","sourceNumber":"0268n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 29 anos refere descarga papilar espontânea da mama esquerda há 1 mês, sanguinolenta. É tabagista, faz uso de anticoncepcional hormonal oral e nunca engravidou. Sua avó materna teve câncer de mama aos 72 anos. Nega outras queixas. O exame ginecológico e das mamas foi normal. Em relação a essa paciente, é CORRETO afirmar que:","options":{"A":"A principal hipótese diagnóstica é de carcinoma mamário, e a paciente deve realizar ductografia.","B":"Deve ser realizada biópsia guiada por ultrassonografia, pois aos 29 anos as mamas são densas e a mamografia tem menor sensibilidade.","C":"A paciente deve ser submetida à ressonância magnética, em razão da idade.","D":"A citologia do líquido de descarga papilar é o melhor exame para o diagnóstico com altíssima sensibilidade.","E":"Uma das hipóteses diagnósticas é o papiloma intraductal."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149671","ankiGuid":"f{p5*+,5bL"},{"id":"anki-ginecologia-doencas-benignas-da-mama-d0524258cf7da02a","number":"0269n","sourceNumber":"0269n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 32 anos, procura pronto-atendimento no oitavo dia pós parto vaginal no termo, relatando calafrios, febre e mastalgia esquerda. Paciente refere hipertensão arterial crônica desde os 13 anos de idade e acompanha com nefrologista por doença renal crônica não dialítica. Ao exame clínico bom estado geral, corada, temperatura oral de 38,4°C, FC: 110 BPM, PA 98 x 60 mmHg, abdome indolor a palpação, útero contraído, loquia fisiológica, toque vaginal; colo grosso, posterior, impérvio. A imagem demonstra a inspeção mamária: Palpação mamária esquerda limitada pela dor, sem identificação de tumoração.\n\nNesse momento, a conduta é:","options":{"A":"Internação, introdução de ampicilina e gentamicina","B":"Ambulatorial, introdução de cefalexina","C":"Internação, introdução de clindamicina","D":"Ambulatorial, introdução de ciprofloxacina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-55bbca97b495588efa0b11373dc245116bbed0a4.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149672","ankiGuid":"ew6k?8u6V@"},{"id":"anki-ginecologia-doencas-benignas-da-mama-1650c0934dc29362","number":"0270n","sourceNumber":"0270n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 33a, G2P2C0A0, comparece ao pronto atendimento por quadro de dor mamária bilateral, mais intensa há 15 dias. Nega trauma, antecedentes de mastite e tabagismo atual ou pregresso. Trabalha em linha de produção de bijuterias. Refere uso regular e adequado de pílula anticoncepcional oral combinada, hoje no terceiro dia de pausa. Antecedentes pessoais e familiares negativos, inclusive oncológicos. Nunca fez mamografia. Exame físico: mamas de médio volume, simétricas, dolorosas nos quadrantes superiores, expressão das árvores ductais negativas bilateralmente, sem outras alterações. Axilas e fossas supraclaviculares bilateralmente livres. A hipótese diagnóstica é:","options":{"A":"Mastalgia de origem extramamária com piora catamenial.","B":"Câncer de mama bilateral nos quadrantes superiores externos.","C":"Fibroadenomatose mamária.","D":"Papilomas intraductais bilateralmente com ectasia ductal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149673","ankiGuid":"x.W/!.t+.W"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b3b63ec557e9dd19","number":"0271n","sourceNumber":"0271n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 18 anos procura a emergência na 4ª semana pós-parto referindo febre e dor mamária. O exame físico demonstra mamas ingurgitadas, com área de hiperemia e calor em quadrante superior externo direito. A ultrassonografia não identifica áreas de abcesso. Com relação à amamentação, deve-se orientar a paciente a:","options":{"A":"Manter em livre demanda em ambas as mamas.","B":"Utilizar cabergolina, visando a suspensão da amamentação.","C":"Espaçar as mamadas em relação aos horários de tomada de antibióticos, pois eles passam para o leite.","D":"Ordenhar e desprezar o leite procedente da mama infectada, devido às modificações na sua composição."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149674","ankiGuid":"rYXenad*E("},{"id":"anki-ginecologia-doencas-benignas-da-mama-437813549bc2ddb5","number":"0272n","sourceNumber":"0272n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Puérpera, que se encontra no 15º dia pós-parto, veio à consulta por dor mamária e febre. As imagens da inspeção estática e do achado ultrassonográfico da mama ( o retângulo representa o transdutor linear) estão reproduzidas abaixo.\n\nQual o diagnóstico mais provável e qual a conduta correspondente?","options":{"A":"Mastite puerperal - administração de antimicrobiano por via intravenosa por 3 dias.","B":"Mastite puerperal - administração de antimicrobiano por via oral por 7 dias.","C":"Galactocele - punção com agulha grossa.","D":"Abscesso de mama - drenagem, sem uso de antimicrobiano.","E":"Abscesso de mama - drenagem e administração de antimicrobiano oral por 21 dias."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-98c31b05803b85e60b2f1d2fda45431abdee4438.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149675","ankiGuid":"jHaenH{d;W"},{"id":"anki-ginecologia-doencas-benignas-da-mama-f88f0eb6bcdb18a1","number":"0273n","sourceNumber":"0273n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 24 anos, puérpera no 9º dia pós-parto normal, procura o ambulatório de mastologia com dor na mama esquerda durante e após as mamadas, ardência no mamilo e prurido. Os sintomas começaram há 2 dias sem queda do estado geral ou febre. Ao exame, foi observada hiperemia e descamação da pele do complexo areolopapilar. Qual o seu diagnóstico?","options":{"A":"Carcinoma inflamatório.","B":"Monilíase areolomamilar.","C":"Fissuras pelo aleitamento.","D":"Mastite puerperal.","E":"Doença de Paget da mama."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149676","ankiGuid":"AOiVN<vPtb"},{"id":"anki-ginecologia-doencas-benignas-da-mama-784fd86745657808","number":"0274n","sourceNumber":"0274n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Durante a consulta de puericultura de um recém-nascido de 25 dias de vida, a mãe da criança apresenta febre, prostração e dor em seios. Ao exame da mãe, a mama direita está hiperemiada e quente, sem outras alterações. As condutas adequadas para esse caso são:","options":{"A":"Antibiótico oral, interrupção do aleitamento pelo seio afetado e extração manual do leite.","B":"Antibiótico oral, manutenção do aleitamento materno e extração manual do leite, se necessário.","C":"Anti-inflamatório oral e compressa quente, interrupção do aleitamento pelo seio afetado e extração manual do leite.","D":"Anti-inflamatório oral e compressa quente, manutenção do aleitamento materno e extração manual do leite, se necessário."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149677","ankiGuid":"M,t?/[hJ1d"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b697d65b0cc7ea56","number":"0275n","sourceNumber":"0275n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 38 anos apresentando queixa de nódulo doloroso em mama esquerda surgido há 2 semanas, nega febre, rubor ou calor local. Ao exame físico, nódulo palpável de superfície lisa, móvel e doloroso à palpação. A ultrassonografia de mama solicitada mostrou um cisto de 5 cm de diâmetro. Qual a conduta ideal para essa paciente?","options":{"A":"Exérese do nódulo.","B":"Punção esvaziadora.","C":"Core Biopsy.","D":"Expectante."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149678","ankiGuid":"L~+#Vz8>9Q"},{"id":"anki-ginecologia-doencas-benignas-da-mama-02bb8cda94d9d225","number":"0276n","sourceNumber":"0276n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher de 20 anos apresenta nódulo na mama esquerda há 12 meses, indolor, sem crescimento nesse período. Exame físico: nódulo de 2 cm de diâmetro no quadrante superior interno da mama esquerda, consistência firme e superfície lisa e móvel. O diagnóstico clínico CORRETO é:","options":{"A":"Hamartoma.","B":"Cisto.","C":"Fibroadenoma.","D":"Tumor filoides."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149679","ankiGuid":"jaVB#FaeSR"},{"id":"anki-ginecologia-doencas-benignas-da-mama-80fb9b803937fac6","number":"0277n","sourceNumber":"0277n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Um dos tumores de mama mais prevalentes em mulheres entre 18 e 30 anos é o fibroadenoma. Sobre esse tumor, assinale a alternativa correta.","options":{"A":"É de origem conjuntiva, porém benigno.","B":"Em jovens, é contraindicado o uso de contraceptivos hormonais combinados.","C":"A conduta é sempre cirúrgica, pois é considerado como fator de risco para o câncer de mama.","D":"A presença de carcinoma em seu interior é muito rara e a forma mais comum é o carcinoma lobular in situ.","E":"Quando presente, deve-se solicitar de rotina a ressonância magnética da mama para diagnóstico diferencial de malignidade."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149680","ankiGuid":"BwN&0.(Qz^"},{"id":"anki-ginecologia-doencas-benignas-da-mama-855cd19d24f75559","number":"0278n","sourceNumber":"0278n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 45 anos com dor mamária e achado súbito de nódulo mama na fase pós menstrual. Assinale o correto:","options":{"A":"O exame físico normal do especialista afasta o diagnóstico de neoplasia maligna.","B":"Tumor sólido sem sombra acústica ao ultrassom requer controle clínico.","C":"O achado de cisto simples não complicado ao ultrassom de mama requer controle clínico e imagem caso não haja maior desconforto.","D":"A presença de dor mamária associada, recomenda o analgésico como tratamento adequado e controle."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149681","ankiGuid":"o`j~@)yn,$"},{"id":"anki-ginecologia-doencas-benignas-da-mama-60b955a634bf6351","number":"0279n","sourceNumber":"0279n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente 30 anos vai ao mastologista apresentando exame clínico das mamas normal, com mamografia BI-RADS 2, por microcalcificações esparsas e alterações sequelares por mamoplastia realizada há 1 ano e ultrassonografia sem achados de outro serviço (BIRADS 1). Relata achado de anatomopatológico da cirurgia plástica, adenose esclerosante associado a múltiplos focos de hiperplasia lobular atípica, bilateralmente. Paciente deseja orientação contraceptiva. Qual seria a conduta?","options":{"A":"Endoceptivo intrauterino ou DIU de cobre.","B":"Métodos de barreira ou definitivo, caso prole constituída.","C":"Contraceptivo oral combinado ou anel vaginal.","D":"Contraceptivo oral monofásico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149682","ankiGuid":"K^XYSw^}fe"},{"id":"anki-ginecologia-doencas-benignas-da-mama-419c503bace1b580","number":"0280n","sourceNumber":"0280n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 50a, com queixa de fogachos intensos e desejando tratamento. Sem comorbidades. Antecedente pessoal: menopausa há 12 meses. Nega câncer na família. Mamografia: área de densidade assimétrica em quadrante súpero-medial da mama direita; ultrassonografia complementar: foco hipoecogênico de 1,5cm na mesma topografia, com o laudo conjunto BIRADS® 4A. Realizada biópsia percutânea (core) de 3 fragmentos. Anatomo-patológico: adenose esclerosante, metaplasia apócrina e fibrose. A conduta é:","options":{"A":"Ressecção cirúrgica da área.","B":"Terapia hormonal.","C":"Ultrassonografia em 6 meses.","D":"Tamoxifeno."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149683","ankiGuid":"O~xQ73l7?C"},{"id":"anki-ginecologia-doencas-benignas-da-mama-c3f0f4ea7f3ee081","number":"0281n","sourceNumber":"0281n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. A presença de derrame papilar unilateral, uniductal, espontâneo, aquoso (água de rocha), com mamografia e ecografia normais, indica a necessidade de realizar:","options":{"A":"Biópsia cirúrgica.","B":"Ductografia.","C":"Prolactina sérica.","D":"Conduta expectante.","E":"Ressonância magnética."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149684","ankiGuid":"KNf?8]vFmH"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5d2da754a133b85e","number":"0282n","sourceNumber":"0282n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Em relação à ectasia ductal, é INCORRETO afirmar que:","options":{"A":"Afeta ductos de médio e grande calibre.","B":"É mais frequente entre mulheres jovens, dos 20 aos 30 anos.","C":"A descarga papilar esverdeada, multiductal e bilateral é um sinal comum.","D":"Está associada à exposição prolongada ao tabagismo.","E":"Relaciona-se com a formação de fístulas areolares."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149685","ankiGuid":"EspfywD0yI"},{"id":"anki-ginecologia-doencas-benignas-da-mama-3d9c46e84590ed0d","number":"0283n","sourceNumber":"0283n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Em mulheres que apresentam descarga papilar unilateral, espontânea, sanguinolenta e oriunda de único ducto, o diagnóstico mais frequente é:","options":{"A":"Câncer de mama.","B":"Papiloma intraductal","C":"Doença fibrocística mamária","D":"Abscesso não lactacional."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149686","ankiGuid":"ONTD#fGt|4"},{"id":"anki-ginecologia-doencas-benignas-da-mama-8481c115c375e91b","number":"0284n","sourceNumber":"0284n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Os sinais e sintomas das patologias das mamas podem ser influenciados pela dinâmica funcional destas, em resposta às variações hormonais próprias da mulher no menacme. Em relação à alteração funcional benigna das mamas, é CORRETO afirmar que:","options":{"A":"Está relacionada à funcionalidade do órgão e não reflete doença na mama.","B":"Mesmo benigna, pode ser definida como fator de risco para câncer de mama.","C":"Mesmo benigna, transforma-se em fator impeditivo de diagnóstico dos cânceres de mama.","D":"Pode ser indicativa de maior agressividade do câncer de mama quando associada com a neoplasia maligna da mama."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149687","ankiGuid":"iLND{IwB&5"},{"id":"anki-ginecologia-doencas-benignas-da-mama-143b68aceffa4bf1","number":"0285n","sourceNumber":"0285n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Lactante no 21º dia de puerpério é atendida com queixa de febre alta (40°C), mal estar e dor nas mamas, após 3 dias de antibioticoterapia. Ao exame físico: identifica-se a presença de edema pronunciado no sulco submamário, vermelhidão da pele e dor intensa à palpação da mama esquerda, com a sensação de que está flutuando. Qual é a principal hipótese diagnóstica?","options":{"A":"Ingurgitamento mamário.","B":"Fissuras mamária.","C":"Abscesso areolar.","D":"Flegmão retromamário.","E":"Mastite parenquimatosa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149688","ankiGuid":"J&I%1_PVKH"},{"id":"anki-ginecologia-doencas-benignas-da-mama-aed4d73b0177290d","number":"0286n","sourceNumber":"0286n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, com nódulo mamário de 3 cm, móvel, fibroelástico, de bordos bem definidos. Na punção biópsia por agulha fina, apresenta blocos celulares planos, com dupla população celular e inúmeras células bipolares soltas. A histologia pode ser observada na figura a seguir (VER IMAGEM).\n\nNesse caso,","options":{"A":"o diagnóstico da paciente é hamartoma mamário, associando-se a clínica, a citologia e a histologia.","B":"a conclusão diagnóstica requer imuno-histoquímica, utilizando-se p63 e calponina.","C":"a conclusão definitiva do diagnóstico requer imuno-histoquímica, utilizando-se RE (receptor de estrógeno), RP (receptor de progesterona) e Ki-67.","D":"o diagnóstico é fibroadenoma, dispensando-se a utilização de marcador imuno- histoquímico para a sua definição."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-51be3ea85f1078065817341002d5e93ef2ff3297.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149689","ankiGuid":"o0-`f;0|W1"},{"id":"anki-ginecologia-doencas-benignas-da-mama-b995b94ca8aa6b6a","number":"0287n","sourceNumber":"0287n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Julgue o próximo item, com relação aos distúrbios pré-malignos e malignos do trato genital feminino e da mama. Mulheres na menacme que apresentam mastalgia, principalmente no período pré-menstrual, e alterações fibróticas no estroma, com formação cística dentro da mama, que variam de acordo com o ciclo menstrual são portadoras de doença fibrocística da mama. Esta é uma doença benigna e, por consequência, não apresenta risco aumentado de desenvolvimento de câncer de mama.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149690","ankiGuid":"eDrB1=PL27"},{"id":"anki-ginecologia-doencas-benignas-da-mama-85b39436a733f90c","number":"0288n","sourceNumber":"0288n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Adolescente, 15 anos, encaminhada ao ginecologista devido a uma ultrassonografia mamária que revelou a presença de imagem anecoide oval com reforço acústico posterior e paredes ovalares circunscritas medindo, no maior diâmetro, 3 cm. Paciente assintomática com antecedente familiar de câncer de mama (tia paterna). Sobre o caso, assinale a alternativa com a melhor conduta a ser dada:","options":{"A":"Introdução da pílula anticoncepcional combinada para a melhora do cisto.","B":"Realização de biopsia guiada por ultrassonografia.","C":"Realização de PAAF.","D":"Acompanhamento da lesão.","E":"Realização de biopsia excisional da lesão."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149691","ankiGuid":"e!&:{Ig7}]"},{"id":"anki-ginecologia-doencas-benignas-da-mama-568feb31c8fff9d4","number":"0289n","sourceNumber":"0289n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"A mastite puerperal infecciosa é uma das principais causas de desmame. Identifique o principal agente etiológico e tratamento adequado.","options":{"A":"Staphylococcus epidermidis; Cefalexina.","B":"Streptococcus viridans; Amoxicilina com clavulanato.","C":"Staphylococcus aureus; Cefalexina.","D":"Streptococcus beta-hemolitico; Amoxicilina com clavulanato.","E":"Streptococcus agalactiae; Clindamicina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149692","ankiGuid":"l(u_1ZICJx"},{"id":"anki-ginecologia-doencas-benignas-da-mama-4c1f3f7c181bdda5","number":"0291n","sourceNumber":"0291n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Puérpera de 23 anos, amamentando há 6 semanas, veio à consulta por apresentar a mama direita endurecida, dolorosa, com hiperemia difusa, edema e área mais amolecida medialmente ao mamilo (VER IMAGEM). Referiu febre baixa, medida sublingualmente, Os linfonodos axilares estavam palpáveis e dolorosos, não muito aumentados.\n\nDiante desse quadro, qual a conduta mais adequada?","options":{"A":"Internação e antibioticoterapia intravenosa.","B":"Incisão e drenagem.","C":"Incisão, drenagem e antibioticoterapia por via oral.","D":"Biópsia de lesão.","E":"Antibioticoterapia e ordenha da mama."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-ee2c83a1fb70bf93a1de9ec51a28afd2a487d9e3.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149694","ankiGuid":"sqj]7~C*6;"},{"id":"anki-ginecologia-doencas-benignas-da-mama-be6537a492a477d1","number":"0292n","sourceNumber":"0292n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"O fluxo papilar funcional é caracterizado por ser:","options":{"A":"Espontâneo, uniductal, bilateral e esverdeado.","B":"Não espontâneo, multiductal, unilateral e seroso.","C":"Não espontâneo, multiductal, bilateral e multicolorido.","D":"Provocado por expressão, uniductal, unilateral e seroso.","E":"Espontâneo, poliductal, unilateral e translúcido."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149695","ankiGuid":"J0%YkM{Q2C"},{"id":"anki-ginecologia-doencas-benignas-da-mama-521da17a6396bf50","number":"0293n","sourceNumber":"0293n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente 48 anos, G3P2A1, relata que há dois meses tem notado uma secreção mamilar avermelhada espontânea à esquerda. Há 3 anos está em uso de terapia hormonal com estrógenos via oral. Nega outras queixas. O exame físico é completamente normal com exceção da presença de fluxo papilar uniductal à expressão, de característica sanguinolenta, em mama esquerda. Exame Complementar: Mamografia solicitada em Unidade Básica de Saúde e realizada há 15 dias, cuja imagem da incidência crânio caudal da mama esquerda está demonstrada a seguir.\n\nQual é a hipótese diagnóstica mais provável para a causa do derrame papilar e qual a conduta mais adequada para confirmação diagnóstica?","options":{"A":"Câncer de mama. Biópsia percutânea guiada por ultrassonografia.","B":"Ectasia ductal. Seguimento clínico.","C":"Fibroadenoma. Exérese cirúrgica da lesão após localização ultrassonográfica.","D":"Papiloma intraductal. Exérese da unidade mamária."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":["question_bank/media/ginecologia-doencas-benignas-da-mama/paste-fdd2c778e9515a42d5a939b2c7d067e866c228df.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149696","ankiGuid":"NFI>Gr}As0"},{"id":"anki-ginecologia-doencas-benignas-da-mama-fa3020a0412852a1","number":"0294n","sourceNumber":"0294n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Quanto às doenças da mama, pode-se afirmar:","options":{"A":"Os fluxos papilares secundários a processos neoplásicos habitualmente são poliductais e bilaterais.","B":"A associação entre tabagismo e mastite periareolar recidivante é frequente.","C":"O carcinoma invasivo é a principal causa de fluxo papilar.","D":"O fibroadenoma é neoplasia mamária rara."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149697","ankiGuid":"k)I|.YjyIZ"},{"id":"anki-ginecologia-doencas-benignas-da-mama-968d0ea2a11c8081","number":"0295n","sourceNumber":"0295n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"O agente microbiano mais comumente associado à mastite puerperal é o (a):","options":{"A":"Staphylococcus epidermidis.","B":"Enterococcus spp.","C":"Escherichia coli.","D":"Staphylococcus aureus."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149698","ankiGuid":"N2eq_Ic=Eb"},{"id":"anki-ginecologia-doencas-benignas-da-mama-4f60e8dad3f8b82f","number":"0296n","sourceNumber":"0296n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Mulher, 62 anos, G3P2A1, casada, procura Unidade Básica de Saúde após ter notado um nódulo na mama esquerda. Está em terapia hormonal com estrógeno e progesterona. Refere nunca ter realizado mamografia. Exame físico: Mama esquerda: nódulo bem delimitado, de 4 cm, móvel e indolor em quadrante superior lateral; Mama direita: normal. Mamografia: mama esquerda com um nódulo de 2,5 x 3,8 cm, homogêneo, circunscrito em quadrante superior lateral; mama direita sem alterações. A CONDUTA É:","options":{"A":"Trocar a terapia hormonal por Isoflavona e realizar ultrassonografia de mama.","B":"Trocar a terapia hormonal por Isoflavona e realizar biópsia excisional.","C":"Suspender a terapia hormonal e realizar ultrassonografia de mama.","D":"Suspender a terapia hormonal e realizar biópsia excisional."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149699","ankiGuid":"H*9g$f<<.%"},{"id":"anki-ginecologia-doencas-benignas-da-mama-1dbe02ff2f83a8dd","number":"0297n","sourceNumber":"0297n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 30 anos apresenta queixa mamária que começa na fase lútea do ciclo menstrual, com ingurgitação mamária, dor, peso e dor à palpação bilateral. Para melhor diagnosticar e tratar essa paciente, deve-se antes classificar esses sintomas em qual dos seguintes tipos de mastalgia?","options":{"A":"Cíclica, anticíclica e extramamária.","B":"Cíclica, alteração fibrocística e extramamária.","C":"Cíclica, displasia mamária e intramamária.","D":"Cíclica, acíclica e extramamária.","E":"Cíclica, alteração fibrocística e intramamária."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149700","ankiGuid":"xowfuwR$St"},{"id":"anki-ginecologia-doencas-benignas-da-mama-6a811cfb90c62387","number":"0298n","sourceNumber":"0298n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Os tumores filoides mamários são tumores fibroepiteliais raros que exibem uma variedade de comportamentos clínicos e patológicos benignos, limítrofes e malignos. O tratamento recomendado é:","options":{"A":"Mastectomia radical sem reconstrução e, após 2 anos livre de tumor, reconstrução com prótese.","B":"Mastectomia total com preservação do complexo aréolo-mamilar (CAM), se o tumor estiver distante 2 cm do CAM.","C":"Excisão local com marcação do leito tumoral para monitoramento e radioterapia adjuvante.","D":"Excisão local ampla, tentando obter uma margem de 1 a 2 cm.","E":"Mastectomia total, se possível com reconstrução e radioterapia adjuvante."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149701","ankiGuid":"wuBZ)=f|ne"},{"id":"anki-ginecologia-doencas-benignas-da-mama-5053ac60f9dbc3eb","number":"0299n","sourceNumber":"0299n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Paciente de 35 anos apresenta, à ultrassonografia, nódulo mamário cístico no quadrante súpero-lateral da mama direita, com 2 cm de diâmetro. Considerando os achados ultrassonográficos que indicam benignidade nesse tipo de lesão, assinale entre as alternativas abaixo, a que está ERRADA :","options":{"A":"Cisto com paredes finas.","B":"Formato redondo regular.","C":"Realce acústico posterior.","D":"Pequena imagem intracística."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149702","ankiGuid":"D>7ACMQ=dd"},{"id":"anki-ginecologia-doencas-benignas-da-mama-ac01c1d2f94acee7","number":"02100n","sourceNumber":"02100n","collectionBlock":"anki:ginecologia-doencas-benignas-da-mama","collectionLabel":"Anki · Doenças Benignas da Mama","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Doenças Benignas da Mama","subtopic":"","stem":"Em relação aos cistos mamários, em qual dos casos a seguir não seria indicado o estudo citológico do fluido intracístico?","options":{"A":"Paciente de 25 anos, com ecografia demonstrando cistos de conteúdo espesso e hipoecogênico.","B":"Paciente de 35 anos, com cisto aneicoide, simples, de 2,2 cm.","C":"Paciente de 28 anos, com mastalgia cíclica e múltiplos microcistos bilaterais à ecografia mamária.","D":"Paciente de 45 anos, com fluido sanguinolento revelado pelo PAAF."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Doenças Benignas da Mama","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Doenças Benignas da Mama","Anki"],"ankiNoteId":"1780579149703","ankiGuid":"FArBCTrFa,"}]};
